/**
 * 自托管产品演示视频（1600×900 / 16:9 WebM）
 * 性能口径：preload="none" + poster —— 首屏不拉取任何视频字节（含 metadata），
 * 封面由静态图承担；点播放才真正下载视频
 * @author 恒哥
 */
import React from 'react';
import { useI18n } from '../../i18n';
import { dc } from '../../i18n/dataCopy';
import './product-video.css';

/**
 * @param {object} props
 * @param {string} props.src
 * @param {string} [props.poster] 封面图 URL（强烈建议传，preload=none 时必须有）
 * @param {string} [props.title]
 * @param {string} [props.durationLabel]
 * @param {string} [props.className]
 * @param {boolean} [props.autoPlay]
 */
export default function ProductVideo({
  src,
  poster,
  title = 'Whaleal Cart demo',
  durationLabel,
  className = '',
  autoPlay = false,
}) {
  // 兜底文案写在组件内部，Layout 的 localizeReact 只能遍历元素树、看不到
  // 函数组件 render 出来的节点，必须在这里就地取语言替换。
  const { locale } = useI18n();
  const fallbackText = dc('Sorry, your browser does not support embedded video.', locale);
  if (!src) return null;

  return (
    <div className={`product-video ${className}`.trim()}>
      <div className="product-video-frame">
        <video
          className="product-video-el"
          controls
          playsInline
          preload={autoPlay ? 'metadata' : 'none'}
          poster={poster}
          width={1600}
          height={900}
          title={title}
          aria-label={title}
          autoPlay={autoPlay}
        >
          <source src={src} type="video/webm" />
          {fallbackText}
        </video>
      </div>
      {(title || durationLabel) && (
        <p className="product-video-caption">
          {durationLabel ? `${durationLabel} · ` : ''}
          {title}
        </p>
      )}
    </div>
  );
}
