/**
 * Whaleal Cart Help Center —— 现挂在 `/help/cart/`
 *
 * 🔴 **2026-10-13 由 `/help/` 迁到 `/help/cart/`**：`/help/` 改为**帮助中心索引**
 *    （`src/pages/help/index.js` + `src/data/help.js` 的平台 help 族）。
 *    本页内容**一字未改**，只动路径 —— 因为它承载的外部依赖不能断：
 *    ① `cart-rescue-java/SHOPIFY_REVIEW_NOTES.md` 登记给 Shopify 审核的
 *       **Help Center = https://www.whaleal.com/help**（那个 URL 现在落在索引页，
 *       索引页第一屏就是「Whaleal Cart」入口 ⇒ 审核方点进去仍一步到位）；
 *    ② Cart 后台产品内的帮助入口 `cart-rescue-ui/src/App.jsx` → `www.whaleal.com/help/`；
 *    ③ App Store 旧链桩 `src/pages/cart-rescue/index.js` 的 `navigate('/help/')`。
 *    **这三处都指向 `/help/`，所以 `/help/` 必须继续存在**。改这三处要动 cart 仓
 *    （= 推 main 即重启生产），本次刻意不动。
 *
 * 多语言：文案全部来自 i18n/dictionaries/help.js（en/de/fr 三份，逐条对应）
 * 🔴 该字典严格对应本页原有 6 个 section / 8 张功能卡 / 3 档定价 / 13 条 FAQ /
 *    4 组排障，未增未减。
 * ⚠️ `/help/cart/` **不在** `src/i18n/config.js` 的 `LOCALIZED_PAGES` 里 ——
 *    加回 de/fr 时它会指向英文原路径（与 `/help/` 现在的处置一致）。
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import ProductVideo from '../../components/ProductVideo';
import { usePageI18n } from '../../i18n';
import helpCopy from '../../i18n/dictionaries/help';
import {
  PRODUCT_NAME,
  MESSAGING_CONSOLE_URL,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
  SHOPIFY_INSTALL_PAGE_PATH,
  CART_VIDEO_WALKTHROUGH_3MIN,
} from '../../constants/brand';
import '../../styles/legal-page.css';

export default function WhalealCartHelp({ pageContext }) {
  const { locale, localePath: lp } = usePageI18n(pageContext);
  const c = helpCopy[locale] || helpCopy.en;

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={c.meta.title}
        description={c.meta.description}
        pathname="/help/cart"
        hrefLang={locale}
      />
      <div className="page-container about-page">
        <div className="page-header about-header">
          <h1>{c.meta.h1}</h1>
          <p>{c.meta.sub}</p>
        </div>

        <div className="about-content">
          {/* What is Whaleal Cart */}
          <section className="about-section">
            <h2>{c.what.title}</h2>
            <p>{c.what.p1}</p>
            <p>{c.what.p2}</p>
            <div style={{
              background: '#f0fdfa',
              padding: '20px',
              borderRadius: '8px',
              border: '1px solid #ffcfc7',
              marginBottom: '20px',
              marginTop: '20px'
            }}>
              <h3 style={{ marginTop: 0, color: '#115e59' }}>{c.what.freeTitle}</h3>
              <p style={{ marginBottom: 0 }}>
                <strong>{c.what.freeLine1}</strong> {c.what.freePer} {c.what.freeArrow}{' '}
                <strong>{c.what.freeLine2}</strong> {c.what.freeNote}<br/>
                {c.what.freeFoot}
              </p>
            </div>
          </section>

          {/* Why Cart Recovery Matters */}
          <section className="about-section">
            <h2>{c.why.title}</h2>
            <p>{c.why.lead}</p>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginTop: '20px' }}>
              {c.why.cards.map((card) => (
                <div key={card.title} style={{ textAlign: 'center', padding: '20px', background: '#f9fafb', borderRadius: '8px' }}>
                  <div style={{ fontSize: '2.25rem', marginBottom: '10px' }}>{card.icon}</div>
                  <h3 style={{ fontSize: '1rem' }}>{card.title}</h3>
                  <p style={{ fontSize: '0.875rem', color: '#666' }}>{card.text}</p>
                </div>
              ))}
            </div>
          </section>

          {/* Quick Start */}
          <section className="about-section">
            <h2>{c.start.title}</h2>
            <p>{c.start.lead}</p>

            <ProductVideo
              src={CART_VIDEO_WALKTHROUGH_3MIN.src}
              poster={CART_VIDEO_WALKTHROUGH_3MIN.poster}
              title={CART_VIDEO_WALKTHROUGH_3MIN.title}
              durationLabel={CART_VIDEO_WALKTHROUGH_3MIN.durationLabel}
            />

            <div style={{
              background: '#f9fafb',
              padding: '24px',
              borderRadius: '8px',
              border: '1px solid #e5e7eb',
              marginBottom: '20px'
            }}>
              <h3 style={{ color: 'var(--primary-color)', marginTop: 0 }}>{c.start.step1Title}</h3>
              <p>
                {c.start.step1p1a}{' '}
                <Link to={lp(SHOPIFY_INSTALL_PAGE_PATH)} className="about-link">{c.start.step1link}</Link>
                {c.start.step1p1b} <code>{c.start.step1code}</code>{c.start.step1p1c}{' '}
                <strong>{PRODUCT_NAME}</strong>
              </p>
              <p>
                {c.start.step1p2a}{' '}
                <a href={SHOPIFY_APP_STORE_URL} target="_blank" rel="noopener noreferrer">{PRODUCT_NAME} {c.start.step1p2b} {SHOPIFY_APP_STORE_LABEL}</a>.
              </p>
            </div>

            <div style={{
              background: '#f9fafb',
              padding: '24px',
              borderRadius: '8px',
              border: '1px solid #e5e7eb',
              marginBottom: '20px'
            }}>
              <h3 style={{ color: 'var(--primary-color)', marginTop: 0 }}>{c.start.step2Title}</h3>
              <p>
                {c.start.step2p1a}{' '}
                <Link to={lp('/products/')} className="about-link">{c.start.step2p1b}</Link>{' '}
                <strong>{c.start.step2on} / {c.start.step2off}</strong> {c.start.step2p1c}{' '}
                <strong>{c.start.step2toneFriendly}</strong>, <strong>{c.start.step2tonePro}</strong>,{' '}
                <strong>{c.start.step2toneUrgency}</strong>. {c.start.step2p1d}
              </p>
              <p>{c.start.step2p2a}</p>
            </div>

            <div style={{
              background: '#f9fafb',
              padding: '24px',
              borderRadius: '8px',
              border: '1px solid #e5e7eb',
              marginBottom: '20px'
            }}>
              <h3 style={{ color: 'var(--primary-color)', marginTop: 0 }}>{c.start.step3Title}</h3>
              <p>{c.start.step3p1a}</p>
              <p>
                {c.start.step3p2a}{' '}
                <Link to={lp('/customers/')} className="about-link">{c.start.step3p2b}</Link>
                {c.start.step3p2c || ''}
              </p>
            </div>
          </section>

          {/* Features Overview */}
          <section className="about-section">
            <h2>{c.features.title}</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px' }}>
              {c.features.cards.map((card) => (
                <div key={card.title} style={{ background: '#fff', padding: '20px', borderRadius: '8px', border: '1px solid #e5e7eb' }}>
                  <h3 style={{ fontSize: '1rem', marginTop: 0 }}>
                    {card.icon} {card.title}
                  </h3>
                  <p style={{ fontSize: '0.875rem', color: '#666', margin: 0 }}>{card.text}</p>
                  {card.badge && (
                    // 🔴 用内联样式而非 .product-card-tier —— 那个类定义在 page.css，
                    //    而本页只 import legal-page.css，Layout 也没全局引入 page.css
                    //    ⇒ 引用它会得到一个无样式的裸文本。
                    <span style={{
                      display: 'inline-block',
                      marginTop: '10px',
                      background: '#f0fdfa',
                      border: '1px solid #ffcfc7',
                      borderRadius: '999px',
                      color: '#0f766e',
                      fontSize: '0.7rem',
                      fontWeight: 700,
                      letterSpacing: '0.04em',
                      padding: '0.2rem 0.65rem',
                      textTransform: 'uppercase',
                    }}>{card.badge}</span>
                  )}
                </div>
              ))}
            </div>
          </section>

          {/* Pricing Plans */}
          <section className="about-section">
            <h2>{c.pricing.title}</h2>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '20px' }}>
              {c.pricing.plans.map((plan) => {
                const featured = plan.badge !== '';
                return (
                  <div
                    key={plan.name}
                    style={{
                      background: '#fff',
                      padding: '24px',
                      borderRadius: '12px',
                      border: `2px solid ${featured ? 'var(--primary-color)' : '#e5e7eb'}`,
                      textAlign: 'center',
                      ...(featured ? { transform: 'scale(1.05)' } : {})
                    }}
                  >
                    {plan.badge && (
                      <div style={{ background: 'var(--primary-color)', color: '#fff', padding: '4px 12px', borderRadius: '20px', display: 'inline-block', fontSize: '0.75rem', marginBottom: '10px' }}>
                        {plan.badge}
                      </div>
                    )}
                    <h3 style={{ marginTop: 0, color: '#333' }}>{plan.name}</h3>
                    <div style={{ fontSize: '2rem', fontWeight: 'bold', color: '#333', marginBottom: '10px' }}>
                      {plan.price}
                      {plan.period && (
                        <span style={{ fontSize: '0.875rem', fontWeight: 'normal' }}>{plan.period}</span>
                      )}
                    </div>
                    <p style={{ color: '#666', fontSize: '0.875rem' }}>{plan.note}</p>
                    <hr style={{ margin: '20px 0' }} />
                    <ul style={{ textAlign: 'left', fontSize: '0.875rem', paddingLeft: '20px' }}>
                      {plan.features.map((f) => <li key={f}>{f}</li>)}
                    </ul>
                  </div>
                );
              })}
            </div>
          </section>

          {/* FAQ */}
          <section className="about-section">
            <h2>{c.faq.title}</h2>

            {c.faq.items.map((item) => (
              <details key={item.q} style={{ marginBottom: '15px', padding: '16px', background: '#f9fafb', borderRadius: '8px' }}>
                <summary style={{ fontWeight: '600', cursor: 'pointer' }}>{item.q}</summary>
                <div style={{ marginTop: '10px', fontSize: '0.875rem' }}>
                  {item.a && <p>{item.a}</p>}
                  {item.aIntro && <p>{item.aIntro}</p>}
                  {item.aBullets && (
                    <ul>
                      {item.aBullets.map((b) => (
                        <li key={b.v}>{b.k ? <><strong>{b.k}</strong> {b.v}</> : b.v}</li>
                      ))}
                    </ul>
                  )}
                  {item.aOutro && <p>{item.aOutro}</p>}
                  {item.smsLinkText && (
                    <p>
                      <a href={MESSAGING_CONSOLE_URL} className="about-link" target="_blank" rel="noopener noreferrer">
                        {item.smsLinkText}
                      </a>
                    </p>
                  )}
                  {item.installLinkText && (
                    <p>
                      <Link to={lp(SHOPIFY_INSTALL_PAGE_PATH)} className="about-link">{item.installLinkText}</Link>
                    </p>
                  )}
                  {item.tailText && (
                    <p>
                      {item.tailText}{' '}
                      <Link to={lp('/pricing/')} className="about-link">{item.pricingLinkText}</Link>
                    </p>
                  )}
                </div>
              </details>
            ))}
          </section>

          {/* Best Practices */}
          <section className="about-section">
            <h2>{c.best.title}</h2>
            <p>{c.best.lead}</p>

            {c.best.cards.map((card) => (
              <div key={card.title} style={{ background: '#fff', padding: '20px', borderRadius: '8px', border: '1px solid #e5e7eb', marginBottom: '20px' }}>
                <h3 style={{ marginTop: 0 }}>{card.icon} {card.title}</h3>
                <ul>
                  {card.items.map((it) => (
                    <li key={it.v}>
                      {it.k ? (
                        it.k.endsWith(':') || it.k.endsWith('!')
                          ? <><strong>{it.k}</strong> {it.v}</>
                          : <><strong>{it.k}</strong> {it.v}</>
                      ) : it.v}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </section>

          {/* Troubleshooting */}
          <section className="about-section">
            <h2>{c.trouble.title}</h2>

            {c.trouble.groups.map((g) => (
              <div key={g.title} style={{ background: '#fef2f2', padding: '20px', borderRadius: '8px', border: '1px solid #fecaca', marginBottom: '20px' }}>
                <h3 style={{ marginTop: 0, color: '#dc2626' }}>{g.title}</h3>
                <ol style={{ fontSize: '0.875rem' }}>
                  {g.steps.map((s) => (
                    <li key={s.v}>{highlightKey(s.v, s.k)}</li>
                  ))}
                </ol>
              </div>
            ))}
          </section>

          {/* Contact */}
          <section className="about-section">
            <h2>{c.contact.title}</h2>
            <p>{c.contact.lead}</p>

            <div style={{ background: '#f9fafb', padding: '24px', borderRadius: '8px', marginBottom: '20px' }}>
              <p style={{ marginBottom: '10px' }}>
                <strong>{c.contact.emailLabel}</strong>{' '}
                <a href={`mailto:${c.contact.email}`} className="about-link">{c.contact.email}</a>
              </p>
              <p style={{ marginBottom: '10px' }}>
                <strong>{c.contact.responseLabel}</strong> {c.contact.response}
              </p>
              <p>
                <strong>{c.contact.storeLabel}</strong>{' '}
                <a href={SHOPIFY_APP_STORE_URL} target="_blank" rel="noopener noreferrer" className="about-link">{PRODUCT_NAME}</a>
              </p>
            </div>

            <div style={{ marginTop: '30px' }}>
              <Link to={lp('/privacy/')} className="about-link" style={{ marginRight: '20px' }}>{c.contact.privacy}</Link>
              <Link to={lp('/terms/')} className="about-link" style={{ marginRight: '20px' }}>{c.contact.terms}</Link>
              <Link to={lp('/gdpr/')} className="about-link">{c.contact.gdpr}</Link>
            </div>
          </section>
        </div>
      </div>
    </Layout>
  );
}

/**
 * 把句子里的重点短语加粗。
 * ⚠️ 排障步骤是「整句译文 + 一个关键短语」两段拼出来的，加粗靠短语匹配而不是
 * 在译文里插标签 —— 否则每种语言的标签都得单独维护，且加错位置很难发现。
 */
function highlightKey(text, key) {
  if (!key || !text.includes(key)) return text;
  const [before, after] = text.split(key);
  return (
    <>
      {before}
      <strong>{key}</strong>
      {after}
    </>
  );
}
